// number of hash functions

static uint8_t bits[(M + 7) / 8];   // the bitmap, all zeros at start

// Any good hash function; each seed gives an independent-looking hash.
extern uint64_t hash(const char *x, uint32_t seed);

void bloom_insert(const char *x) {
    for (uint32_t i = 0; i < K; i++) {
        uint64_t pos = hash(x, i) % M;
        bits[pos / 8] |= (uint8_t)(1u << (pos % 8));   // set the bit to 1
    }
}

bool bloom_lookup(const char *x) {
    for (uint32_t i = 0; i < K; i++) {
        uint64_t pos = hash(x, i) % M;
        if (!(bits[pos / 8] & (1u << (pos % 8))))      // found a 0 bit
            return false;                               // definitely absent
    }
    return true;                                        // maybe present
}
